        "verdict": {
          "verdict": "partly",
          "asOf": "2026-11-16",
          "summary": "CBP counted about 458 miles of new wall by January 2021, but most replaced older fencing. In places with no barrier before, about 52 miles of primary and 33 miles of secondary wall were built. Most of the unfenced border stayed unfenced.",
          "attempt": null,
          "review": null,
          "evidence": [
            {
              "what": "CBP/USACE Border Wall Status, 22 January 2021 (table \"In locations where no barriers previously existed\", completed)",
              "url": "https://cdn.factcheck.org/UploadedFiles/CBP-Border-Wall-Status-Paper_as-of-01222021-FINAL-003.pdf",
              "publisher": "U.S. Customs and Border Protection (copy hosted by FactCheck.org)",
              "date": "2021-01-22",
              "secondary": false
            }
          ],
          "uncertainty": {
            "verdict": "contested",
            "note": "The criterion sets no length. A reader who counts any new barrier where none stood would call this kept; one who counts the 458 miles of replacement as building \"a wall\" would too. A reader who expects most of the unfenced border to be closed would call it broken."
          }
        }
